'use strict';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]||ICONS.grid}</svg>`;
const logo=`<svg class="brand-mark" viewBox="0 0 38 38" aria-hidden="true"><path d="M5 31V7h15c16 0 16 17 0 17H5m16-1 12 8" fill="none" stroke="currentColor" stroke-width="3.2"/><path d="M5 7 33 31" fill="none" stroke="currentColor" stroke-width="1.6"/></svg>`;
const DEFAULTS={template:'enterprise',font:'Inter',mode:'light',density:'comfortable',expression:'balanced',accent:null,motion:true,favorites:[],selected:[]};
let stored={};try{stored=JSON.parse(localStorage.getItem('regenesy-studio-v1')||'{}')}catch{}
const state={...DEFAULTS,...stored};
if(!TEMPLATES.some(t=>t.id===state.template))state.template='enterprise';
if(!['Inter','Manrope','DM Sans','IBM Plex Sans','Plus Jakarta Sans'].includes(state.font))state.font='Inter';
if(!['light','dark'].includes(state.mode))state.mode='light';
if(!['compact','comfortable'].includes(state.density))state.density='comfortable';
if(!['rigorous','balanced','expressive'].includes(state.expression))state.expression='balanced';
state.favorites=Array.isArray(state.favorites)?state.favorites.filter(id=>COMPONENTS.some(c=>c.id===id)):[];
state.selected=Array.isArray(state.selected)?state.selected.filter(id=>TEMPLATES.some(t=>t.id===id)):[];
if(state.accent&&!/^#[0-9a-f]{6}$/i.test(state.accent))state.accent=null;
let componentCategory='Tutti',componentSearch='',onlyFavorites=false,templateCategory='Tutti',tableSector='idrico',tableEngine='datatables',tableStatus='',tableQuery='',gridApi=null,dataTable=null,tableRows=[],tableData={},period='day',pocPaused=false,mockDevice='desktop',mockSector='idrico',toastTimer,previousFocus=null;
const save=()=>{try{localStorage.setItem('regenesy-studio-v1',JSON.stringify(state))}catch{}};
const currentTemplate=()=>TEMPLATES.find(t=>t.id===state.template);
function appearance(){document.body.dataset.template=state.template;document.body.dataset.mode=state.mode;document.body.dataset.density=state.density;document.body.dataset.expression=state.expression;document.body.classList.toggle('no-motion',!state.motion);document.documentElement.style.setProperty('--font',`'${state.font}',system-ui,sans-serif`);if(state.accent){document.documentElement.style.setProperty('--accent',state.accent);document.documentElement.style.setProperty('--accent-hover',state.accent);document.documentElement.style.setProperty('--tint',`color-mix(in srgb, ${state.accent} 9%, var(--surface))`)}else{['--accent','--accent-hover','--tint'].forEach(x=>document.documentElement.style.removeProperty(x))}}
function route(){const bits=location.hash.replace(/^#\/?/,'').split('/');return {page:bits[0]||'panoramica',sector:SECTORS[bits[1]]?bits[1]:'idrico'}}
function titleFor(r){return {'panoramica':'Panoramica','template':'Template','componenti':'Componenti','tabelle':'Tabelle avanzate','mockup':'Mockup','confronta':'Confronta','poc':`POC ${SECTORS[r.sector].name}`}[r.page]||'Panoramica'}
function btn(label,action,style='',ico='',extra=''){return `<button class="btn ${style}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`}
function link(label,url,style='',ico=''){return `<a class="btn ${style}" href="#/${url}" data-route>${ico?icon(ico):''}${label}</a>`}
function badge(text,color='green',dot=false){return `<span class="badge ${color}">${dot?'<i class="dot"></i>':''}${text}</span>`}
function navItem(label,page,ico,count='',sector=''){const r=route();const active=sector?r.page==='poc'&&r.sector===sector:r.page===page;return `<a href="#/${sector?'poc/'+sector:page}" class="nav-item ${active?'active':''}" ${active?'aria-current="page"':''} data-route>${icon(ico)}<span>${label}</span>${count?`<span class="nav-count">${count}</span>`:''}${sector?`<i class="sector-dot" style="background:${SECTORS[sector].color}"></i>`:''}</a>`}
function shell(content){const r=route();return `<aside class="sidebar" id="sidebar"><a class="brand" href="#/panoramica" aria-label="Regenesy Studio, panoramica" data-route>${logo}<div class="brand-name">Regenesy<span>Design studio</span></div></a><div class="workspace"><i class="dot"></i>Il tuo spazio di progettazione${icon('down')}</div><nav aria-label="Navigazione principale"><p class="nav-label">Workspace</p><div class="nav-group">${navItem('Panoramica','panoramica','grid')}${navItem('Template','template','layers','06')}${navItem('Componenti','componenti','components','36')}${navItem('Tabelle avanzate','tabelle','table')}${navItem('Mockup','mockup','mockup')}${navItem('Confronta','confronta','compare')}</div><p class="nav-label">Proof of concept</p><div class="nav-group">${navItem('Elettrico','poc','bolt','','elettrico')}${navItem('Gas','poc','flame','','gas')}${navItem('Idrico','poc','drop','','idrico')}</div></nav><div class="side-bottom"><div class="side-help"><strong>Il tuo prossimo prodotto inizia qui.</strong>Esplora, combina e trova il linguaggio della tua rete.<button data-action="help">Come funziona lo studio ${icon('arrow')}</button></div><button class="nav-item" data-action="settings" style="background:transparent;width:100%;text-align:left;margin:0 0 14px">${icon('settings')}Personalizza studio</button><div class="side-user"><div class="user-avatar">CM</div><div class="user-text">Il tuo workspace<small>Configurazione salvata in locale</small></div>${icon('shield')}</div></div></aside><div class="mobile-scrim" data-action="close-nav" aria-hidden="true"></div><div class="app-main"><header class="topbar"><div class="topbar-left"><button class="icon-btn mobile-menu" data-action="mobile-nav" aria-label="Apri navigazione" aria-controls="sidebar" aria-expanded="false">${icon('menu')}</button><div class="breadcrumbs"><span>Design Studio</span>${icon('chevron')}<strong>${titleFor(r)}</strong></div></div><div class="topbar-right"><button class="search-trigger" data-action="search" aria-label="Cerca nello studio">${icon('search')}<span>Cerca nello studio</span><kbd>⌘ K</kbd></button><span class="top-separator"></span><button class="icon-btn" data-action="toggle-mode" aria-label="${state.mode==='dark'?'Attiva tema chiaro':'Attiva tema scuro'}">${icon(state.mode==='dark'?'sun':'moon')}</button><button class="icon-btn help-trigger" data-action="help" aria-label="Guida allo studio">${icon('help')}</button><button class="icon-btn" data-action="notifications" aria-label="Novità dello studio">${icon('bell')}<i class="notification-dot"></i></button></div></header><main class="content" id="main" tabindex="-1">${content}${footer()}</main></div><div id="compare-root">${compareBar()}</div>`}
function heading(eyebrow,title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`}
function footer(){return `<footer class="page-footer"><span>Regenesy Studio <span style="margin:0 5px;color:#bec7c8">/</span> Il design delle reti, a modo tuo.</span><div class="footer-links"><a href="https://christianmusumeci00.github.io/regenesy-flux/" target="_blank" rel="noopener">Ispirato a Regenesy Flux ${icon('arrow').replace('class="icon','style="width:10px;height:10px;vertical-align:middle" class="icon')}</a><span class="version-pill"><i class="dot"></i>Studio v1.0</span></div></footer>`}
function previewVars(t){return `--preview-accent:${t.color};--preview-bg:${t.bg};--preview-side:${t.side};--preview-radius:${t.radius/2}px;--preview-font:'${t.font}';--preview-surface:${t.id==='control'?'#1b2a36':'#fff'};--preview-ink:${t.id==='control'?'#d9e8ee':'#283c35'};--preview-muted:${t.id==='control'?'#829ca7':'#87958e'}`}
function lineChart(color='var(--accent)',variant=0,area=true){const paths=['M0 59C15 57 16 46 30 48S48 64 62 44 80 50 95 35 112 47 128 30 145 40 160 21 177 30 193 14 210 22 225 9 244 17 260 6','M0 54C16 54 20 40 35 46S53 58 68 40 89 43 105 25 127 39 141 28 159 36 175 16 198 24 215 12 239 24 260 8','M0 61C20 60 25 49 40 51S60 41 73 45 95 30 109 33 131 44 145 24 164 32 181 17 199 24 215 13 240 20 260 7'];const p=paths[variant%3];return `<svg viewBox="0 0 260 75" preserveAspectRatio="none" role="img" aria-label="Andamento dimostrativo in crescita"><path d="M0 22H260M0 47H260M0 72H260" fill="none" stroke="currentColor" opacity=".055"/>${area?`<path d="${p}V75H0Z" fill="${color}" opacity=".07"/>`:''}<path d="${p}" fill="none" stroke="${color}" stroke-width="1.8" vector-effect="non-scaling-stroke"/></svg>`}
function miniApp(t,sector='idrico'){const s=SECTORS[sector];return `<div class="mini-app" style="${previewVars(t)}"><div class="mini-side"><div class="mini-logo"></div><i></i><i></i><i></i><i></i><i></i></div><div class="mini-main"><div class="mini-top">${s.product} <span style="float:right">Panoramica della rete</span></div><div class="mini-title">La tua rete, sotto controllo.</div><div class="mini-stats"><div class="mini-stat"><span>${s.metric}</span><strong>${s.value}</strong></div><div class="mini-stat"><span>Dispositivi attivi</span><strong>${s.devices}</strong></div><div class="mini-stat"><span>In linea</span><strong>${s.connected}%</strong></div></div><div class="mini-chart">${s.chart}${t.id==='executive'?`<div class="mini-chart-bars">${[35,50,42,62,50,72,59,82,63,75,92,78,90,83,99].map(n=>`<i style="height:${n}%"></i>`).join('')}</div>`:lineChart(t.color,TEMPLATES.indexOf(t))}</div></div></div>`}
function templateCard(t,small=false){const applied=t.id===state.template;return `<article class="template-card ${applied?'applied':''}"><div class="template-visual" style="${previewVars(t)};background:${t.bg}">${!small?`<label class="template-checkbox"><input type="checkbox" data-select-template="${t.id}" ${state.selected.includes(t.id)?'checked':''} aria-label="Confronta ${t.name}"> Confronta</label>`:''}${miniApp(t)}</div><div class="template-meta"><div class="between"><h3>${t.name}</h3>${badge(t.tag,t.id==='aurora'?'purple':t.id==='executive'?'blue':t.id==='soft'?'amber':'green')}</div><p>${small?t.level:t.desc}</p><div class="template-info"><i class="dot" style="background:${t.color}"></i><span>${t.font}</span>${applied?`<span class="applied-label" style="margin-left:auto">${icon('check')}In uso</span>`:btn('Applica','apply-template','small','',`data-id="${t.id}"`)}</div></div>${!small?`<div class="template-footer"><span class="muted" style="font-size:9px">${t.personality}</span>${btn('Anteprima','preview-template','ghost','expand',`data-id="${t.id}"`)}</div>`:''}</article>`}
function compareBar(){if(!state.selected.length||route().page==='confronta')return '';return `<div class="compare-bar"><span><strong>${state.selected.length}</strong> template selezionat${state.selected.length===1?'o':'i'}</span>${link(`Confronta ${state.selected.length>1?'('+state.selected.length+')':''}`,'confronta','','compare')}<button class="icon-btn" data-action="clear-compare" aria-label="Azzera selezione">${icon('close')}</button></div>`}
function home(){return `${heading('Benvenuto nel tuo design lab','Idee chiare. Interfacce migliori.','Un unico spazio per esplorare, confrontare e dare forma al futuro delle utility.',btn('Personalizza studio','settings','','settings'))}<section class="studio-banner" aria-label="Esplora i template di Regenesy"><div class="banner-copy"><div class="eyebrow"><i class="dot"></i> Dall’idea all’interfaccia</div><h2>La stessa rete.<br><span>Il tuo stile.</span></h2><p>Dal rigore enterprise alla libertà creativa. Trova il linguaggio giusto per il tuo prodotto.</p>${link('Esplora i template','template','','arrow')}</div><div class="banner-art" aria-hidden="true"><div class="hero-window"><div class="window-chrome"><i class="window-dot"></i><i class="window-dot"></i><i class="window-dot"></i><span><i class="dot"></i>AquaSense · Panoramica</span></div><div class="hero-dash-title">La tua rete, sotto controllo.<span>Ultime 24 ore</span></div><div class="hero-metrics"><div class="hero-metric"><small>Volume distribuito</small><strong>18.420 <em>m³</em></strong><span>↗ 3,6% rispetto a ieri</span></div><div class="hero-metric"><small>Contatori in linea</small><strong>96,8 <em>%</em></strong><span>↗ 0,4 pt questa settimana</span></div><div class="hero-metric"><small>Rendimento rete</small><strong>81,4 <em>%</em></strong><span>↗ 1,2 pt questo mese</span></div></div><div class="hero-chart"><div>Volume distribuito<span>Oggi — — Ieri</span></div>${lineChart('#4e8d73')}</div></div><div class="floating-note">${icon('check')}<div>Il design prende forma.<span>Ogni dettaglio, al posto giusto.</span></div></div></div></section><div class="overview-statbar">${[['layers','06','Template da esplorare'],['components','36','Componenti interattivi'],['bolt','03','Settori, un linguaggio'],['table','02','Motori per i tuoi dati']].map(([i,n,l])=>`<div class="overview-stat"><div class="stat-symbol">${icon(i)}</div><div><strong>${n}</strong><span>${l}</span></div></div>`).join('')}</div><div class="section-heading"><div><h2>Trova la tua direzione <small>01 — TEMPLATE</small></h2><p>Personalità diverse. La stessa attenzione ai dettagli.</p></div>${link('Tutti i template','template','ghost','arrow')}</div><section class="template-grid overview-templates" aria-label="Template in evidenza">${[TEMPLATES[0],TEMPLATES[2],TEMPLATES[3]].map(t=>templateCard(t,true)).join('')}</section><div class="section-heading"><div><h2>Tre reti. Possibilità reali. <small>02 — PROOF OF CONCEPT</small></h2><p>Esplora il design nel suo contesto operativo.</p></div>${badge('Dati dimostrativi','blue')}</div><section class="poc-preview-grid" aria-label="Proof of concept per settore">${Object.entries(SECTORS).map(([id,s],i)=>`<a href="#/poc/${id}" class="poc-preview" style="--sector:${s.color}" data-route><div class="poc-preview-head"><div class="sector-icon">${icon(s.icon)}</div><div><h3>${s.product}</h3><div class="sub">Rete ${id==='idrico'?'idrica':id==='elettrico'?'elettrica':'gas'}</div></div><div class="arrow-circle">${icon('arrow')}</div></div><div class="poc-metric"><strong>${s.secondaryValue}</strong><span>${s.secondaryUnit}</span></div><div class="poc-chart">${lineChart(s.color,i)}</div><div class="poc-preview-bottom"><span>${s.secondary}</span><span class="live"><i class="dot"></i>POC interattiva</span></div></a>`).join('')}</section><div class="overview-bottom"><section class="panel component-teaser"><h3 class="teaser-title">Piccoli dettagli. Un grande sistema.</h3><p>Dai badge alle metriche, ogni componente parla la stessa lingua.</p><div class="teaser-row">${badge('In linea','green',true)}${badge('Da verificare','amber',true)}${btn('Nuovo dispositivo','demo-toast','small','plus')}<div class="demo-avatars"><span class="avatar" style="width:26px;height:26px;font-size:8px">CM</span><span class="avatar" style="width:26px;height:26px;font-size:8px">AL</span></div></div>${link('Esplora i 36 componenti','componenti','ghost','arrow')}</section><section class="panel table-teaser"><div class="stat-symbol">${icon('table')}</div><div><h3 class="teaser-title">Dati complessi, interazioni semplici.</h3><p>Due motori reali per cercare, filtrare, ordinare ed esportare.</p><div class="flex">${badge('DataTables','green')}${badge('AG Grid Community','blue')}</div>${link('Prova le tabelle avanzate','tabelle','ghost','arrow')}</div></section></div>`}
function templatesPage(){return `${heading('La tua direzione visiva','Sei modi di essere Regenesy.','Scegli un template o selezionane più di uno per confrontarli. Ogni stile si applica a tutto lo studio.',btn('Personalizza','settings','','settings'))}<div class="filter-toolbar"><div class="filter-tabs" role="tablist" aria-label="Stili dei template">${['Tutti','Istituzionale','Professionale','Creativo','Tecnico','Informale'].map(x=>`<button role="tab" aria-selected="${templateCategory===x}" class="filter-tab ${templateCategory===x?'active':''}" data-action="template-category" data-value="${x}">${x}${x==='Tutti'?'<small>6</small>':''}</button>`).join('')}</div><span class="muted" style="font-size:10px">${icon('check').replace('class="icon','style="width:12px;height:12px;vertical-align:middle" class="icon')} Selezione multipla per il confronto</span></div><section class="template-grid" aria-label="Catalogo template">${TEMPLATES.filter(t=>templateCategory==='Tutti'||t.personality===templateCategory).map(t=>templateCard(t)).join('')}</section><div class="panel" style="padding:20px 23px;margin-top:24px;display:flex;gap:14px;align-items:center"><div class="stat-symbol">${icon('settings')}</div><div><h3 style="font-size:12px">Il template è solo il punto di partenza.</h3><p class="muted" style="font-size:11px;margin-top:4px">Combina cinque font, tre stili di componenti, due densità e la tua palette. Le preferenze restano salvate nel browser.</p></div></div>`}
function comparePage(){const ids=state.selected.length?state.selected:['enterprise','executive'];return `${heading('Scegli con uno sguardo','Stessa funzione. Personalità diverse.','Confronta gli stessi dati, componenti e scelte tipografiche nei template selezionati.',link('Modifica selezione','template','','layers'))}<div class="compare-grid">${ids.map(id=>{const t=TEMPLATES.find(x=>x.id===id);return `<section class="compare-column" style="${previewVars(t)}"><div class="compare-header"><div><h2>${t.name}</h2><small style="color:var(--preview-muted)">${t.personality}</small></div>${btn(t.id===state.template?'In uso':'Applica','apply-template','small',t.id===state.template?'check':'',`data-id="${t.id}"`)}</div><div class="compare-body">${miniApp(t)}<div class="compare-detail">${badge(t.font,'')}${badge(t.tag,'')}</div><div class="compare-sample"><h3>Un linguaggio coerente.</h3><p style="font-size:10px;color:var(--preview-muted);margin-bottom:13px">12.840 dispositivi. Tutte le informazioni al posto giusto.</p><span class="preview-status">● In linea</span><button class="sample-btn" data-action="demo-toast">Aggiungi dispositivo</button></div><div class="spec-line"><span>Font principale</span><strong>${t.font}</strong></div><div class="spec-line"><span>Raggio delle superfici</span><strong>${t.radius} px</strong></div><div class="spec-line"><span>Orientamento</span><strong>${t.personality}</strong></div><div class="spec-line"><span>Formalità</span><strong>${t.score}/100</strong></div><div class="demo-progress"><div class="progress-track" style="background:#81988d22"><i style="width:${t.score}%;background:${t.color}"></i></div></div></div></section>`}).join('')}</div>`}
function switchControl(label,checked,attributes=''){return `<label class="switch-line"><span>${label}</span><span class="switch"><input type="checkbox" ${checked?'checked':''} ${attributes}><i></i></span></label>`}
function signal(n){return `<span class="signal-bars" aria-hidden="true">${[1,2,3,4].map((x)=>`<i style="${n<70&&x===4?'opacity:.25':''}"></i>`).join('')}</span>${n}%`}
function statusBadge(status){return badge(status,status==='Online'?'green':status==='Allarme'?'red':'amber',true)}
function componentDemo(id){switch(id){
case 'kpi':return `<div class="demo-kpi"><div class="between"><small>Volume distribuito</small>${icon('drop')}</div><strong>18.420 <em>m³</em></strong>${badge('↗ 3,6% rispetto a ieri','green')}</div>`;
case 'badge':return `<div class="flex" style="flex-wrap:wrap;justify-content:center">${statusBadge('Online')}${statusBadge('Allarme')}${statusBadge('Offline')}</div><div class="flex">${badge('NB-IoT','blue')}${badge('Nuovo','purple')}${badge('Pianificato','')}</div>`;
case 'button':return `${btn('Nuovo dispositivo','demo-toast','primary','plus')}<div class="flex">${btn('Annulla','demo-toast','small')}${btn('Esporta','demo-download','small','download')}</div>`;
case 'card':return `<div class="demo-device">${icon('server')}<div><strong>Gateway Nord 01</strong><small>LoRaWAN · Distretto Nord</small></div>${badge('Online','green',true)}</div>`;
case 'avatar':return `<div class="demo-avatars"><span class="avatar">CM</span><span class="avatar">AL</span><span class="avatar">FR</span><span class="avatar">+4</span></div><small class="muted" style="font-size:9px">Il tuo team di rete</small>`;
case 'chip':return `<div class="flex demo-chip-group"><button class="demo-chip active" data-action="demo-chip">${icon('check')}Tutti</button><button class="demo-chip" data-action="demo-chip">Nord</button><button class="demo-chip" data-action="demo-chip">Centro</button></div><small class="muted" style="font-size:9px">Tocca un filtro per selezionarlo</small>`;
case 'input':return `<label class="demo-field"><span>Nome dispositivo</span><input class="input" placeholder="Es. Gateway Nord 01" maxlength="60"><small class="field-hint">Un nome riconoscibile per il tuo team.</small></label>`;
case 'select':return `<label class="demo-field"><span>Distretto di appartenenza</span><select class="input" aria-label="Distretto di appartenenza"><option>Distretto Nord</option><option>Distretto Centro</option><option>Distretto Sud</option></select><small class="field-hint">Seleziona una delle tre aree.</small></label>`;
case 'switch':return `<div style="width:100%;max-width:230px;display:grid;gap:16px">${switchControl('Notifiche in tempo reale',true,'aria-label="Notifiche in tempo reale"')}${switchControl('Report automatici',false,'aria-label="Report automatici"')}</div>`;
case 'checkbox':return `<div class="demo-radios"><label class="check-label"><input type="checkbox" checked> Letture e consumi</label><label class="check-label"><input type="checkbox" checked> Eventi e allarmi</label><label class="check-label"><input type="checkbox"> Informazioni diagnostiche</label></div>`;
case 'radio':return `<div class="demo-radios">${['Ogni 15 minuti','Ogni ora','Una volta al giorno'].map((x,i)=>`<label class="check-label"><input type="radio" name="frequency-${$('#overlay-root')?.children.length?'modal':'gallery'}" ${i===1?'checked':''}>${x}</label>`).join('')}</div>`;
case 'slider':return `<div class="demo-field"><div class="between"><span>Soglia di attenzione</span><strong data-range-value>75%</strong></div><input class="range demo-range" type="range" min="0" max="100" value="75" aria-label="Soglia di attenzione" style="margin-top:17px"><small class="field-hint">Trascina per regolare la soglia.</small></div>`;
case 'date':return `<label class="demo-field"><span>Data di lettura</span><input class="input" type="date" value="2026-10-29" aria-label="Data di lettura"><small class="field-hint">Analizza i dati del giorno selezionato.</small></label>`;
case 'upload':return `<label class="demo-upload">${icon('download')}<strong>Scegli un file di letture</strong><br><span data-upload-name>CSV o TXT · elaborazione locale</span><input type="file" class="demo-file" accept=".csv,.txt" aria-label="Carica un file di letture"></label>`;
case 'tabs':return `<div class="segmented demo-tabs"><button class="active" data-action="demo-tab">Panoramica</button><button data-action="demo-tab">Letture</button><button data-action="demo-tab">Eventi</button></div><small class="muted" data-tab-text style="font-size:9px">Stato generale del dispositivo</small>`;
case 'breadcrumb':return `<div class="breadcrumbs"><span>Rete</span>${icon('chevron')}<span>Contatori</span>${icon('chevron')}<strong>Dettaglio</strong></div>`;
case 'pagination':return `<div class="demo-pagination"><button data-action="demo-page" data-page="prev" aria-label="Pagina precedente">‹</button>${[1,2,3,4].map(n=>`<button class="${n===1?'active':''}" data-action="demo-page" data-page="${n}">${n}</button>`).join('')}<button data-action="demo-page" data-page="next" aria-label="Pagina successiva">›</button></div><small class="muted" data-page-text style="font-size:9px">Pagina 1 di 4</small>`;
case 'stepper':return `<div class="demo-stepper"><span class="step-circle done">${icon('check')}</span><span class="step-line"></span><span class="step-circle active">2</span><span class="step-line"></span><span class="step-circle">3</span></div><div class="between" style="width:100%;font-size:8px;color:var(--muted)"><span>Dispositivo</span><span>Connessione</span><span>Conferma</span></div>${btn('Passo successivo','demo-step','small','arrow')}`;
case 'accordion':return `<details class="demo-accordion"><summary>Dettagli tecnici ${icon('down')}</summary><p>Tecnologia: NB-IoT<br>Intervallo letture: 15 min<br>Firmware: 2.4.1</p></details><details class="demo-accordion"><summary>Informazioni di rete ${icon('down')}</summary><p>Gateway: GW-NORD-01<br>Ultima connessione: 10:42</p></details>`;
case 'menu':return `<div class="demo-menu"><button data-action="demo-toast">${icon('eye')}Visualizza dettaglio</button><button data-action="demo-download">${icon('download')}Esporta letture</button><button data-action="demo-toast">${icon('copy')}Duplica configurazione</button></div>`;
case 'alert':return `<div class="demo-alert">${icon('alert')}<div><strong>Pressione da verificare</strong>Il valore supera la soglia impostata.</div></div>${btn('Verifica dispositivo','demo-alert','ghost','arrow')}`;
case 'toast':return `<small class="muted" style="font-size:10px">Una conferma, al momento giusto.</small>${btn('Mostra notifica','demo-toast','','bell')}`;
case 'modal':return `<small class="muted" style="font-size:10px">Un dettaglio senza perdere il contesto.</small>${btn('Apri dialog','demo-modal','','expand')}`;
case 'progress':return `<div class="demo-progress"><div class="between"><span>Importazione letture</span><strong data-progress-value>68%</strong></div><div class="progress-track"><i style="width:68%"></i></div></div>${btn('Avanza','demo-progress','small','arrow')}`;
case 'skeleton':return `<div class="skeleton"><i></i><div><span></span><span></span></div></div><div class="skeleton"><i></i><div><span></span><span></span></div></div><small class="muted" style="font-size:8px">Caricamento dei dati di rete…</small>`;
case 'empty':return `<div class="demo-empty">${icon('folder')}<strong>Nessun dispositivo, per ora.</strong><p>Inizia aggiungendo il primo alla tua rete.</p></div>${btn('Aggiungi dispositivo','demo-modal','small','plus')}`;
case 'table':return `<table class="simple-table"><thead><tr><th>Dispositivo</th><th>Stato</th><th>Lettura</th></tr></thead><tbody>${makeRows('idrico',3).map((r,i)=>`<tr><td class="mono">H2O-00${i+1}</td><td>${statusBadge(i===2?'Offline':'Online')}</td><td>${(123+i*72).toLocaleString('it-IT')} m³</td></tr>`).join('')}</tbody></table>${link('Apri griglie avanzate','tabelle','ghost','arrow')}`;
case 'sparkline':return `<div class="between" style="width:100%;font-size:10px"><span class="muted">Consumi settimanali</span>${badge('↗ 12,4%','green')}</div><div style="width:100%">${lineChart()}</div>`;
case 'bar':return `<div class="demo-bars" aria-label="Consumi settimanali dimostrativi">${[45,68,52,88,73,58,94].map((x,i)=>`<button style="height:${x}%" data-action="bar-value" data-value="${['Lun','Mar','Mer','Gio','Ven','Sab','Dom'][i]}: ${x*120} m³" aria-label="${['Lunedì','Martedì','Mercoledì','Giovedì','Venerdì','Sabato','Domenica'][i]}: ${x*120} metri cubi"></button>`).join('')}</div><small class="muted" style="font-size:9px">Seleziona una barra per leggere il valore</small>`;
case 'donut':return `<div class="flex" style="gap:23px"><div class="donut" role="img" aria-label="70% NB-IoT, 18% LoRaWAN, 12% wM-Bus"><div><strong>70%</strong>NB-IoT</div></div><div class="stack" style="font-size:9px;color:var(--muted)"><span>● NB-IoT <strong>70%</strong></span><span style="opacity:.7">● LoRaWAN <strong>18%</strong></span><span style="opacity:.5">● wM-Bus <strong>12%</strong></span></div></div>`;
case 'heatmap':return `<div class="heatmap" role="img" aria-label="Mappa dell’intensità dei consumi su quattro settimane">${Array.from({length:48},(_,i)=>`<i style="opacity:${.1+((i*7)%10)/12}" title="Giorno ${i+1}: ${(i*137)%1200} m³"></i>`).join('')}</div><div class="between" style="width:100%;font-size:8px;color:var(--muted)"><span>Ultime 4 settimane</span><span>Basso → Alto</span></div>`;
case 'gauge':return gauge('3,6','bar');
case 'odometer':return `<div class="odometer" aria-label="Lettura cumulata: 1284647,6 metri cubi">${'12846476'.split('').map((n,i)=>`<span>${i===7?',':''}${n}</span>`).join('')}</div><small class="muted" style="font-size:9px">Volume cumulato · m³</small>`;
case 'network':return networkSvg('idrico',true);
case 'alarm':return `<button class="alarm-item critical" data-action="demo-alert"><span class="alarm-symbol">${icon('drop')}</span><span><strong>Possibile perdita</strong><small>Via Roma, 12 · Distretto Nord</small></span><span>8 min fa</span></button><button class="alarm-item" data-action="demo-alert"><span class="alarm-symbol">${icon('wifi')}</span><span><strong>Assenza di comunicazione</strong><small>H2O-00840208 · Centro</small></span><span>22 min fa</span></button>`;
case 'timeline':return `<div class="timeline"><div class="timeline-entry"><strong>Gateway nuovamente online</strong><small>10:42 · GW-NORD-01</small></div><div class="timeline-entry"><strong>Nuove letture acquisite</strong><small>10:30 · 1.240 dispositivi</small></div><div class="timeline-entry"><strong>Intervento completato</strong><small>10:15 · Distretto Centro</small></div></div>`;
default:return ''}}
function gauge(value,unit){return `<div class="gauge" role="img" aria-label="Valore attuale ${value} ${unit}, entro i limiti"><svg viewBox="0 0 140 80"><path d="M12 70a58 58 0 0 1 116 0" fill="none" stroke="var(--line)" stroke-width="8" stroke-linecap="round"/><path d="M12 70a58 58 0 0 1 94-46" fill="none" stroke="var(--sector,var(--accent))" stroke-width="8" stroke-linecap="round"/><path d="M70 68 92 32" stroke="var(--ink)" stroke-width="2" stroke-linecap="round"/><circle cx="70" cy="68" r="4" fill="var(--ink)"/></svg><div class="gauge-value">${value} <small>${unit}</small></div></div>`}
function networkSvg(sector,mini=false){const s=SECTORS[sector];const coords=[[4,100],[145,45],[145,160],[290,10],[290,100],[290,190]];const paths=['M102 122C130 122 120 67 145 67','M102 122C130 122 120 182 145 182','M243 67C265 67 265 32 290 32','M243 67C270 67 265 122 290 122','M243 182C265 182 265 122 290 122','M243 182C270 182 265 212 290 212'];return `<svg class="network-map" style="${mini?'height:130px;max-width:300px;':''}--sector:${s.color}" viewBox="0 0 396 246" role="group" aria-label="${s.network}. Seleziona un nodo per i dettagli."><defs><pattern id="mapgrid-${sector}-${mini?'mini':'full'}" width="20" height="20" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".65" fill="currentColor" opacity=".075"/></pattern></defs><rect width="396" height="246" fill="url(#mapgrid-${sector}-${mini?'mini':'full'})"/>${paths.map(p=>`<path class="network-line" d="${p}"/><path class="flow-line" d="${p}"/>`).join('')}${coords.map(([x,y],i)=>`<g class="network-node" transform="translate(${x},${y})" data-action="node-detail" data-sector="${sector}" data-index="${i}" role="button" tabindex="0" aria-label="${s.nodes[i]}, ${s.nodeValues[i]}, apri dettagli"><rect width="98" height="44" rx="6"/><circle class="node-ring" cx="17" cy="21" r="10"/><circle class="node-dot" cx="17" cy="21" r="3"/><text class="node-label" x="32" y="18">${s.nodes[i]}</text><text class="node-value" x="32" y="31">${s.nodeValues[i]}</text></g>`).join('')}</svg>`}
function componentCard(c){const fav=state.favorites.includes(c.id);return `<article class="component-card"><div class="component-preview">${componentDemo(c.id)}</div><div class="component-meta"><div><h3>${c.name}</h3><p>${c.desc}</p></div><div class="flex" style="gap:1px"><button class="icon-btn fav ${fav?'active':''}" data-action="favorite" data-id="${c.id}" aria-label="${fav?'Rimuovi dai':'Aggiungi ai'} preferiti: ${c.name}" aria-pressed="${fav}">${icon('star')}</button><button class="icon-btn" data-action="component-detail" data-id="${c.id}" aria-label="Dettaglio ${c.name}">${icon('expand')}</button></div></div></article>`}
function filteredComponents(){return COMPONENTS.filter(c=>(componentCategory==='Tutti'||c.category===componentCategory)&&(!onlyFavorites||state.favorites.includes(c.id))&&(c.name+' '+c.desc+' '+c.category).toLowerCase().includes(componentSearch.toLowerCase()))}
function componentCards(){const matches=filteredComponents();return matches.length?matches.map(componentCard).join(''):`<div class="empty-results">${icon('search')}<h3>Nessun componente trovato</h3><p>${onlyFavorites?'Aggiungi componenti ai preferiti con la stella.':'Prova con un’altra ricerca o una categoria diversa.'}</p>${btn('Azzera filtri','clear-component-filters','ghost','reset')}</div>`}
function componentsPage(){return `${heading('Ogni dettaglio conta','La tua libreria di possibilità.','36 componenti da provare, salvare e confrontare. Cambia stile e guardali trasformarsi.',btn('Stile componenti','settings','','settings'))}<div class="filter-toolbar"><div class="filter-tabs" role="tablist" aria-label="Categorie componenti">${['Tutti','Fondamentali','Form','Navigazione','Feedback','Dati','Rete'].map(x=>`<button role="tab" aria-selected="${componentCategory===x}" class="filter-tab ${componentCategory===x?'active':''}" data-action="component-category" data-value="${x}">${x}</button>`).join('')}</div><div class="flex"><label class="filter-search">${icon('search')}<input id="component-search" placeholder="Cerca un componente…" value="${esc(componentSearch)}" aria-label="Cerca un componente"></label><button class="btn small ${onlyFavorites?'primary':''}" data-action="only-favorites" aria-pressed="${onlyFavorites}">${icon('star')}Preferiti</button></div></div><div class="between" style="margin:-3px 0 13px;font-size:9px;color:var(--muted)"><span id="component-count">${filteredComponents().length} ${filteredComponents().length===1?'componente':'componenti'}</span><span>Template ${currentTemplate().name} · ${state.font}</span></div><section class="component-grid" id="component-grid" aria-label="Catalogo componenti">${componentCards()}</section>`}
function updateComponentGrid(){$('#component-grid').innerHTML=componentCards();$('#component-count').textContent=`${filteredComponents().length} ${filteredComponents().length===1?'componente':'componenti'}`}
function tablesPage(){const rows=makeRows(tableSector);return `${heading('Il dato diventa esperienza','Tabelle, senza compromessi.','Due motori reali, gli stessi dati: prova ricerca, filtri, ordinamento e gestione delle colonne.',btn('Esporta CSV','export-table','','download'))}<div class="table-summary">${[['Dispositivi nel dataset',rows.length,'server'],['Dispositivi online',rows.filter(x=>x.status==='Online').length,'wifi'],['Richiedono attenzione',rows.filter(x=>x.status==='Allarme').length,'alert'],['Tecnologie integrate','03','layers']].map(([l,n,i])=>`<div class="panel table-stat"><div class="between"><small>${l}</small>${icon(i)}</div><strong>${n}</strong></div>`).join('')}</div><section class="panel"><div class="table-panel-header"><div><h2>Registro dispositivi</h2><p>Dati dimostrativi · seleziona una riga per i dettagli</p></div><div class="table-engine-tabs" role="tablist" aria-label="Motore tabella"><button role="tab" aria-selected="${tableEngine==='datatables'}" class="${tableEngine==='datatables'?'active':''}" data-action="table-engine" data-value="datatables">DataTables <span class="engine-tag">2.3</span></button><button role="tab" aria-selected="${tableEngine==='aggrid'}" class="${tableEngine==='aggrid'?'active':''}" data-action="table-engine" data-value="aggrid">AG Grid <span class="engine-tag">Community</span></button></div></div><div class="table-toolbar"><label class="filter-search">${icon('search')}<input id="table-search" placeholder="Cerca matricola, indirizzo…" value="${esc(tableQuery)}" aria-label="Cerca nei dispositivi"></label><select class="input" id="table-sector" aria-label="Settore tabella">${Object.entries(SECTORS).map(([id,s])=>`<option value="${id}" ${id===tableSector?'selected':''}>${s.name}</option>`).join('')}</select><select class="input" id="table-status" aria-label="Filtra per stato"><option value="">Tutti gli stati</option>${['Online','Allarme','Offline'].map(x=>`<option ${tableStatus===x?'selected':''}>${x}</option>`).join('')}</select>${btn('Azzera','reset-table','small','reset')}</div><div class="grid-container">${tableEngine==='datatables'?'<table id="devices-dt" class="display" aria-label="Registro dispositivi DataTables"></table>':'<div id="ag-grid" aria-label="Registro dispositivi AG Grid"></div>'}</div><div class="table-note"><span>${tableEngine==='datatables'?'Ordina dalle intestazioni · filtra e sfoglia il registro':'Riordina e ridimensiona le colonne · filtri per colonna · doppio clic sul consumo per modificarlo'}</span><span>Motore: <a target="_blank" rel="noopener" href="${tableEngine==='datatables'?'https://datatables.net/':'https://www.ag-grid.com/javascript-data-grid/'}">${tableEngine==='datatables'?'DataTables 2.3.5':'AG Grid Community 34.3.1'}</a></span></div></section><div class="engine-explainer"><section class="panel"><h3>DataTables <span class="muted" style="font-weight:400">/ Il registro operativo</span></h3><p>Ricerca immediata, ordinamento, paginazione e selezione del numero di righe. Una soluzione chiara per consultare registri e letture.</p><div class="flex">${badge('Ricerca','green')}${badge('Ordinamento','')}${badge('Paginazione','')}</div></section><section class="panel"><h3>AG Grid Community <span class="muted" style="font-weight:400">/ Lo spazio di analisi</span></h3><p>Filtri per colonna, selezione multipla, colonne spostabili e consumi modificabili. Le modifiche restano nella sessione corrente.</p><div class="flex">${badge('Filtri colonna','blue')}${badge('Editing locale','')}${badge('Selezione multipla','')}</div></section></div>`}
function initTable(){tableRows=tableData[tableSector]||(tableData[tableSector]=makeRows(tableSector));if(tableEngine==='datatables'){if(!window.DataTable){$('#devices-dt').outerHTML='<p class="panel-pad">Il motore DataTables non è disponibile. Ricarica la pagina.</p>';return}dataTable=new DataTable('#devices-dt',{data:tableRows,pageLength:10,lengthMenu:[10,25,50,100],order:[[0,'asc']],autoWidth:false,layout:{topStart:'pageLength',topEnd:null,bottomStart:'info',bottomEnd:'paging'},language:{lengthMenu:'Mostra _MENU_ righe',info:'_START_–_END_ di _TOTAL_ dispositivi',infoEmpty:'Nessun dispositivo',infoFiltered:'(da _MAX_ totali)',zeroRecords:'Nessun dispositivo corrisponde ai filtri.',emptyTable:'Nessun dispositivo disponibile',paginate:{first:'«',previous:'‹',next:'›',last:'»'},aria:{orderable:'Attiva per ordinare',orderableReverse:'Attiva per invertire l’ordine',orderableRemove:'Attiva per rimuovere l’ordinamento',paginate:{first:'Prima pagina',previous:'Pagina precedente',next:'Pagina successiva',last:'Ultima pagina'}}},columns:[{data:'id',title:'Matricola',className:'mono'},{data:'address',title:'Indirizzo'},{data:'district',title:'Distretto'},{data:'status',title:'Stato',render:(v,type)=>type==='display'?statusBadge(v):v},{data:'technology',title:'Tecnologia'},{data:'consumption',title:'Consumo',render:(v,type,r)=>type==='display'?`${v.toLocaleString('it-IT')} <span class="muted">${r.unit}</span>`:v},{data:'signal',title:'Segnale',render:(v,type)=>type==='display'?signal(v):v}],createdRow:(row,data)=>{row.dataset.deviceId=data.id;row.tabIndex=0;row.setAttribute('aria-label',`Apri dispositivo ${data.id}`)}});filterTable()}else{if(!window.agGrid){$('#ag-grid').innerHTML='<p class="panel-pad">AG Grid non è disponibile. Ricarica la pagina.</p>';return}const css=getComputedStyle(document.body);const theme=agGrid.themeQuartz.withParams({accentColor:css.getPropertyValue('--accent').trim(),backgroundColor:css.getPropertyValue('--surface').trim(),foregroundColor:css.getPropertyValue('--ink').trim(),borderColor:css.getPropertyValue('--line').trim(),headerBackgroundColor:css.getPropertyValue('--surface2').trim(),headerTextColor:css.getPropertyValue('--muted').trim(),fontFamily:state.font,fontSize:11,spacing:5,rowHeight:state.density==='compact'?36:45,headerHeight:39,wrapperBorder:false,borderRadius:0});gridApi=agGrid.createGrid($('#ag-grid'),{theme,rowData:tableRows,defaultColDef:{sortable:true,filter:true,floatingFilter:true,resizable:true,minWidth:115,flex:1},columnDefs:[{field:'id',headerName:'Matricola',minWidth:180,pinned:'left',cellClass:'mono'},{field:'address',headerName:'Indirizzo',minWidth:175},{field:'district',headerName:'Distretto',minWidth:150},{field:'status',headerName:'Stato',minWidth:120,cellRenderer:p=>statusBadge(p.value)},{field:'technology',headerName:'Tecnologia',minWidth:130},{field:'consumption',headerName:'Consumo',minWidth:135,filter:'agNumberColumnFilter',editable:true,valueFormatter:p=>`${p.value.toLocaleString('it-IT')} ${p.data.unit}`,valueSetter:p=>{const v=Number(String(p.newValue).replace(',','.'));if(!Number.isFinite(v)||v<0){toast('Inserisci un consumo numerico maggiore o uguale a zero.');return false}p.data.consumption=Math.round(v*10)/10;return true}},{field:'signal',headerName:'Segnale',filter:'agNumberColumnFilter',valueFormatter:p=>p.value+'%'}],rowSelection:{mode:'multiRow',enableClickSelection:false},pagination:true,paginationPageSize:10,paginationPageSizeSelector:[10,25,50,100],localeText:{page:'Pagina',of:'di',to:'a',more:'altro',nextPage:'Pagina successiva',lastPage:'Ultima pagina',firstPage:'Prima pagina',previousPage:'Pagina precedente',pageSizeSelectorLabel:'Righe per pagina:',noRowsToShow:'Nessun dispositivo trovato',contains:'Contiene',notContains:'Non contiene',equals:'Uguale a',notEqual:'Diverso da',startsWith:'Inizia con',endsWith:'Finisce con',blank:'Vuoto',notBlank:'Non vuoto',filterOoo:'Filtra…',andCondition:'E',orCondition:'O'},onRowClicked:p=>{if(p.event.target.closest('.ag-selection-checkbox')||p.event.target.closest('[col-id="consumption"]'))return;deviceModal(p.data)},onCellValueChanged:()=>toast('Consumo aggiornato nella sessione corrente. CSV aggiornato.')} );filterTable()}}
function filterTable(){if(dataTable){dataTable.search(tableQuery);dataTable.column(3).search(tableStatus?`^${tableStatus}$`:'',true,false);dataTable.draw()}if(gridApi){gridApi.setGridOption('quickFilterText',tableQuery);gridApi.setFilterModel(tableStatus?{status:{filterType:'text',type:'equals',filter:tableStatus}}:null)}}
function bigChart(sector,periodValue=period){const s=SECTORS[sector];const shift=periodValue==='week'?1:periodValue==='month'?2:0;const values=[44,39,36,40,46,61,77,72,65,70,82,76,72,79,92,85,80,93,87,76,65,70,61,57].map((x,i)=>Math.max(16,Math.min(96,x+Math.sin(i+shift*2)*shift*9)));const pts=values.map((v,i)=>[38+i*15.8,164-v*1.25]);const path=pts.map((p,i)=>(i?'L':'M')+p.map(n=>n.toFixed(1)).join(' ')).join(' ');const yesterday=pts.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(1)} ${(y+15+Math.sin(i)*9).toFixed(1)}`).join(' ');const labels=periodValue==='day'?['00:00','04:00','08:00','12:00','16:00','20:00']:periodValue==='week'?['Lun','Mar','Mer','Gio','Ven','Sab']:['01 ott','06 ott','11 ott','16 ott','21 ott','26 ott'];return `<svg viewBox="0 0 430 200" preserveAspectRatio="none" role="img" aria-label="${s.chart}, ${periodValue==='day'?'andamento nelle 24 ore':periodValue==='week'?'ultima settimana':'ultimo mese'}, dati dimostrativi"><path d="M35 30H421M35 75H421M35 120H421M35 165H421" stroke="var(--line)" stroke-dasharray="3 4" fill="none"/><text x="2" y="33">${sector==='elettrico'?'160':sector==='gas'?'3.000':'900'}</text><text x="6" y="78">${sector==='elettrico'?'120':sector==='gas'?'2.000':'600'}</text><text x="6" y="123">${sector==='elettrico'?'80':sector==='gas'?'1.000':'300'}</text><text x="15" y="168">0</text><path d="${yesterday}" fill="none" stroke="#b1c0b8" stroke-width="1.5" stroke-dasharray="4 5"/><path d="${path}L401.4 165H38Z" fill="${s.color}" opacity=".07"/><path d="${path}" fill="none" stroke="${s.color}" stroke-width="2.2" stroke-linejoin="round" vector-effect="non-scaling-stroke"/>${pts.filter((_,i)=>i%4===0).map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="2.7" fill="var(--surface)" stroke="${s.color}" stroke-width="1.5"><title>${labels[i]}: ${values[i*4]*(sector==='elettrico'?1.6:sector==='gas'?32:9)} ${s.unit}</title></circle>`).join('')}${labels.map((l,i)=>`<text x="${36+i*72}" y="190">${l}</text>`).join('')}</svg>`}
function sectorSwitcher(sector){return `<nav class="poc-switcher" aria-label="Settore proof of concept">${Object.entries(SECTORS).map(([id,s])=>`<a href="#/poc/${id}" class="${id===sector?'active':''}" style="--sector:${s.color}" data-route>${icon(s.icon)}${s.name}</a>`).join('')}</nav>`}
function pocPage(sector){const s=SECTORS[sector];return `<div class="page-heading poc-heading" style="--sector:${s.color}"><div><div class="eyebrow">Proof of concept / ${s.name}</div><h1><span class="sector-icon">${icon(s.icon)}</span>${s.product}<span class="badge blue" style="font-size:9px;letter-spacing:0;font-weight:450">POC</span></h1><p>${s.subtitle}</p></div><div class="heading-actions">${btn('Esporta report','export-poc','','download',`data-sector="${sector}"`)}${btn('Personalizza','settings','','settings')}</div></div><div class="poc-context"><div class="flex"><i class="dot"></i><span id="simulation-status">${pocPaused?'Simulazione in pausa':'Simulazione attiva'}</span>${btn(pocPaused?'Riprendi':'Pausa','pause-poc','small',pocPaused?'play':'pause')}</div>${sectorSwitcher(sector)}<span>29 ottobre 2026 · Dati di esempio</span></div><div class="poc-dashboard ${pocPaused?'poc-paused':''}" style="--sector:${s.color}"><div class="kpi-grid"><article class="kpi-card primary-kpi"><div class="kpi-label">${s.metric}${icon(s.icon)}</div><div class="kpi-number">${s.value}<em>${s.unit}</em></div><div class="kpi-foot"><span class="up">↗ ${s.trend}</span> rispetto a ieri</div></article><article class="kpi-card"><div class="kpi-label">Dispositivi in rete${icon('server')}</div><div class="kpi-number">${s.devices}<em>unità</em></div><div class="kpi-foot"><span class="up">+24</span> nell’ultima settimana</div></article><article class="kpi-card"><div class="kpi-label">Contatori comunicanti${icon('wifi')}</div><div class="kpi-number">${s.connected}<em>%</em></div><div class="kpi-foot"><span class="up">↗ 0,4 pt</span> questa settimana</div></article><article class="kpi-card"><div class="kpi-label">Allarmi aperti${icon('bell')}</div><div class="kpi-number" id="alarm-count">${s.alerts}<em>eventi</em></div><div class="kpi-foot"><span style="color:var(--warning)">3 prioritari</span> da verificare</div></article></div><div class="poc-main-grid"><section class="panel chart-panel"><div class="panel-title"><h2>${s.chart}</h2><div class="segmented" aria-label="Periodo del grafico">${[['day','24h'],['week','7g'],['month','30g']].map(([v,l])=>`<button class="${period===v?'active':''}" data-action="chart-period" data-value="${v}" aria-pressed="${period===v}">${l}</button>`).join('')}</div></div><div class="panel-subtitle" id="chart-period-label">${period==='day'?'Andamento nelle ultime 24 ore':period==='week'?'Andamento settimanale':'Andamento mensile'} · ${s.unit}</div><div class="chart-legend"><span><i></i>Periodo attuale</span><span><i></i>Periodo precedente</span></div><div class="large-chart" id="poc-chart">${bigChart(sector)}</div></section><section class="panel network-panel"><div class="panel-title"><h2>${s.network}</h2>${badge('Simulazione','green',true)}</div><p class="panel-subtitle">Seleziona un nodo per esplorare il dettaglio</p>${networkSvg(sector)}<div class="network-legend"><span><i class="dot" style="color:var(--success)"></i>Regolare</span><span><i class="dot" style="color:var(--warning)"></i>Attenzione</span><span>${s.secondaryValue} ${s.secondaryUnit}</span></div></section></div><div class="poc-secondary"><section class="panel gauge-panel"><h3>${s.pressure}</h3><p class="panel-subtitle">Intervallo ottimale ${s.goal}</p>${gauge(s.pressureValue,s.pressureUnit)}${badge(s.status,'green',true)}</section><section class="panel alarm-panel"><div class="panel-title"><h2>Allarmi recenti</h2>${btn('Vedi tutti','poc-alarms','ghost','arrow',`data-sector="${sector}"`)}</div>${[[s.alert1,'critical','8 min fa'],[s.alert2,'','22 min fa'],['Comunicazione assente','','34 min fa']].map(([a,c,time],i)=>`<button class="alarm-item ${c}" data-action="alarm-detail" data-sector="${sector}" data-index="${i}"><span class="alarm-symbol">${icon(i===2?'wifi':'alert')}</span><span><strong>${a}</strong><small>${s.idPrefix}-${840201+i} · Distretto ${['Nord','Centro','Sud'][i]}</small></span><span>${time}</span></button>`).join('')}</section><section class="panel quality-panel"><h3>${s.quality}</h3><p class="panel-subtitle">Media degli ultimi 30 giorni</p><div class="quality-number">${s.efficiency}<small> %</small></div><div class="demo-progress"><div class="progress-track"><i style="width:${s.efficiency.replace(',','.')}%;background:${s.color}"></i></div></div><div class="quality-meta"><span>Obiettivo</span><strong>${sector==='idrico'?'85,0':'99,5'}%</strong></div></section></div><section class="panel poc-device-table"><div class="panel-title"><h2>Dispositivi in evidenza ${badge('Ultime letture','')}</h2>${btn('Apri registro completo','open-sector-table','ghost','arrow',`data-sector="${sector}"`)}</div><table class="simple-table" aria-label="Dispositivi in evidenza ${s.name}"><thead><tr><th>Matricola</th><th>Indirizzo</th><th>Tecnologia</th><th>Ultima lettura</th><th>Consumo</th><th>Stato</th></tr></thead><tbody>${makeRows(sector,5).map((r,i)=>`<tr class="device-row" data-poc-device="${i}" data-sector="${sector}" tabindex="0" aria-label="Apri ${r.id}"><td class="mono">${r.id}</td><td>${r.address}</td><td>${r.technology}</td><td class="muted">${r.reading.slice(11)}</td><td>${r.consumption.toLocaleString('it-IT')} <span class="muted">${r.unit}</span></td><td>${statusBadge(r.status)}</td></tr>`).join('')}</tbody></table></section><div class="poc-demo-notice">${icon('help')}Dashboard dimostrativa con dati simulati. Le interazioni non modificano dispositivi reali.</div></div>`}
function mockupContent(){const s=SECTORS[mockSector];return `<div class="mockup-frame ${mockDevice}"><div class="window-chrome"><i class="window-dot"></i><i class="window-dot"></i><i class="window-dot"></i><span class="window-address">${s.product.toLowerCase()}.regenesy / panoramica</span>${icon('plus').replace('class="icon','style="width:9px;height:9px" class="icon')}</div><div class="mockup-content"><aside class="mock-side"><strong>R. ${s.product}</strong><span class="active">Panoramica</span><span>Dispositivi</span><span>Letture</span><span>Allarmi</span><span>Impostazioni</span></aside><div class="mock-main"><div class="eyebrow" style="font-size:7px;margin-bottom:5px">La rete, oggi</div><h2>Buongiorno, la rete è stabile.</h2><p>Tutte le informazioni che ti servono. In una sola vista.</p><div class="mock-metrics"><div class="mock-metric">${s.metric}<strong>${s.value} <em>${s.unit}</em></strong></div><div class="mock-metric">Contatori comunicanti<strong>${s.connected}<em> %</em></strong></div><div class="mock-metric">Allarmi aperti<strong>${s.alerts}<em> eventi</em></strong></div></div><div class="mock-chart" style="--sector:${s.color}"><div class="between"><h3>${s.chart}</h3>${badge('Ultime 24 ore','green')}</div><div class="large-chart">${bigChart(mockSector,'day')}</div></div><table class="simple-table"><thead><tr><th>Dispositivo</th><th>Stato</th><th>Ultima lettura</th></tr></thead><tbody>${makeRows(mockSector,3).map(r=>`<tr><td class="mono">${r.id}</td><td>${statusBadge(r.status)}</td><td>${r.reading.slice(11)}</td></tr>`).join('')}</tbody></table></div></div></div>`}
function mockupsPage(){return `${heading('Dal sistema al prodotto','Guardalo prendere forma.','Lo stesso prodotto su desktop, tablet e mobile. Cambia settore e stile per trovare la combinazione giusta.',btn('Esporta mockup','export-mockup','','download'))}<div class="mockup-controls"><div class="segmented" role="group" aria-label="Dispositivo mockup">${[['desktop','Desktop'],['tablet','Tablet'],['mobile','Mobile']].map(([id,label])=>`<button class="${id===mockDevice?'active':''}" data-action="mock-device" data-value="${id}" aria-pressed="${id===mockDevice}">${id==='desktop'?icon('mockup'):''}${label}</button>`).join('')}</div><select class="input" id="mock-sector" aria-label="Settore del mockup" style="width:170px">${Object.entries(SECTORS).map(([id,s])=>`<option value="${id}" ${id===mockSector?'selected':''}>${s.product} · ${s.name}</option>`).join('')}</select><span class="muted" style="font-size:10px">${currentTemplate().name} · ${state.font} ${btn('Cambia stile','settings','ghost','settings')}</span></div><section class="mockup-stage" id="mockup-stage" aria-label="Anteprima del prodotto ${SECTORS[mockSector].name} su ${mockDevice}">${mockupContent()}</section><div class="mockup-caption"><span>${icon('eye').replace('class="icon','style="width:13px;height:13px;vertical-align:middle;margin-right:5px" class="icon')}Mockup di presentazione · ${mockDevice==='desktop'?'Desktop 1440':mockDevice==='tablet'?'Tablet 768':'Mobile 375'} px</span>${link('Apri la POC interattiva',`poc/${mockSector}`,'ghost','arrow')}</div>`}
function render(preserveScroll=false){const y=window.scrollY;if(dataTable){dataTable.destroy();dataTable=null}if(gridApi){gridApi.destroy();gridApi=null}appearance();const r=route();const views={panoramica:home,template:templatesPage,componenti:componentsPage,tabelle:tablesPage,mockup:mockupsPage,confronta:comparePage,poc:()=>pocPage(r.sector)};$('#app').innerHTML=shell((views[r.page]||home)());document.title=`${titleFor(r)} · Regenesy Studio`;if(r.page==='tabelle')initTable();if(r.page==='poc')updateAlarmUI();if(preserveScroll)window.scrollTo(0,y);else window.scrollTo(0,0)}
function toast(message){clearTimeout(toastTimer);$('#toast-root').innerHTML=`<div class="toast" role="status">${icon('check')}<span>${esc(message)}</span><button data-action="close-toast" aria-label="Chiudi notifica">${icon('close')}</button></div>`;toastTimer=setTimeout(()=>$('#toast-root').innerHTML='',4200)}
function closeOverlay(restore=true){$('#overlay-root').innerHTML='';document.body.style.overflow='';if(restore&&previousFocus?.isConnected)previousFocus.focus()}
function setOverlay(html){const replacing=!!$('#overlay-root').children.length;const active=document.activeElement;const focusData={id:active?.id,action:active?.dataset?.action,key:active?.dataset?.key,value:active?.dataset?.value,templateId:active?.dataset?.id};if(!replacing)previousFocus=active;$('#overlay-root').innerHTML=html;document.body.style.overflow='hidden';if(replacing)$$('#overlay-root .overlay,#overlay-root .drawer,#overlay-root .modal').forEach(x=>x.style.animation='none');let el;if(replacing&&focusData.id)el=document.getElementById(focusData.id);if(replacing&&!el&&focusData.action)el=$$('#overlay-root [data-action]').find(x=>x.dataset.action===focusData.action&&x.dataset.key===focusData.key&&x.dataset.value===focusData.value&&x.dataset.id===focusData.templateId);(el||$('#overlay-root input:not([type=hidden]), #overlay-root button, #overlay-root select'))?.focus()}
function modal(title,subtitle,body,actions='',wide=false){setOverlay(`<div class="overlay modal-overlay" data-backdrop><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="modal-header"><div><h2 id="dialog-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-btn" data-action="close-overlay" aria-label="Chiudi dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>${actions?`<div class="modal-footer">${actions}</div>`:''}</section></div>`)}
function openSettings(){const t=currentTemplate();setOverlay(`<div class="overlay" data-backdrop><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="settings-title"><header class="drawer-header"><div><div class="eyebrow" style="margin-bottom:7px;font-size:8px">Il tuo linguaggio visivo</div><h2 id="settings-title">Fallo tuo.</h2><p>Ogni scelta si riflette su tutto lo studio.</p></div><button class="icon-btn" data-action="close-overlay" aria-label="Chiudi personalizzazione">${icon('close')}</button></header><div class="drawer-content"><div class="control-group"><span class="control-label">01 / Template</span><div class="control-template-grid">${TEMPLATES.map(x=>`<button class="control-template ${x.id===state.template?'active':''}" data-action="settings-template" data-id="${x.id}" aria-pressed="${x.id===state.template}" style="--swatch:${x.color}"><i></i>${x.name}</button>`).join('')}</div></div><div class="control-group"><label class="control-label" for="font-select">02 / Tipografia</label><select class="input" id="font-select">${['Inter','Manrope','DM Sans','IBM Plex Sans','Plus Jakarta Sans'].map(f=>`<option ${f===state.font?'selected':''}>${f}</option>`).join('')}</select><div class="font-sample">Aa 0123456789<small>${state.font} · La tua rete, sotto controllo.</small></div></div><div class="control-group"><span class="control-label">03 / Stile dei componenti</span><div class="control-segmented">${[['rigorous','Rigoroso'],['balanced','Equilibrato'],['expressive','Espressivo']].map(([id,l])=>`<button class="${state.expression===id?'active':''}" data-action="setting" data-key="expression" data-value="${id}">${l}</button>`).join('')}</div><p>Dal dettaglio essenziale a forme più morbide ed espressive.</p></div><div class="control-group"><span class="control-label">04 / Colore d’accento</span><div class="palette">${[null,'#257463','#36578b','#7961cf','#ac754b','#3e91b4'].map(c=>`<button class="swatch-btn ${state.accent===c?'active':''}" style="--swatch:${c||t.color}" data-action="accent" data-value="${c||''}" aria-label="${c?'Accento '+c:'Colore originale del template'}" title="${c||'Originale'}">${state.accent===c?icon('check'):''}</button>`).join('')}</div><p>Il primo colore ripristina la palette del template.</p></div><div class="control-group"><span class="control-label">05 / Densità e modalità</span><div class="control-segmented" style="margin-bottom:10px">${[['comfortable','Confortevole'],['compact','Compatta']].map(([id,l])=>`<button class="${state.density===id?'active':''}" data-action="setting" data-key="density" data-value="${id}">${l}</button>`).join('')}</div><div class="control-segmented">${[['light','Tema del template'],['dark','Scuro']].map(([id,l])=>`<button class="${state.mode===id?'active':''}" data-action="setting" data-key="mode" data-value="${id}">${icon(id==='dark'?'moon':'sun').replace('class="icon','style="width:11px;height:11px;vertical-align:middle;margin-right:3px" class="icon')}${l}</button>`).join('')}</div></div><div class="control-group">${switchControl('Animazioni di rete',state.motion,'id="motion-switch"')}<p>Le preferenze di movimento ridotto del dispositivo vengono sempre rispettate.</p></div><div class="control-group"><span class="control-label">Porta con te le tue scelte.</span><div class="flex">${btn('Esporta JSON','export-config','small','download')}<label class="btn small" style="cursor:pointer">${icon('folder')}Importa<input type="file" id="import-config" accept=".json" hidden></label></div><p>Salva o ripristina template, font, preferiti e impostazioni.</p></div></div><footer class="drawer-footer">${btn('Ripristina','reset-config','ghost','reset')}<small><i class="dot"></i>Salvato nel browser</small>${btn('Fatto','close-overlay','primary','check')}</footer></section></div>`)}
function applyTemplate(id,drawer=false){const t=TEMPLATES.find(x=>x.id===id);if(!t)return;state.template=id;state.font=t.font;state.mode='light';state.accent=null;state.expression='balanced';save();if(!drawer)closeOverlay(false);render(true);if(drawer)openSettings();else toast(`Template ${t.name} applicato allo studio.`)}
function updateSetting(key,value){if(!['font','density','expression','mode','motion'].includes(key))return;state[key]=value;save();const scroll=$('.drawer-content')?.scrollTop||0;render(true);openSettings();$('.drawer-content').scrollTop=scroll}
function deviceModal(r){modal(r.id,`${r.name} · ${r.district}`,`<div class="between"><div class="flex"><div class="stat-symbol">${icon('server')}</div><div><h3 style="font-size:13px">${r.address}</h3><small class="muted">Dispositivo dimostrativo</small></div></div>${statusBadge(r.status)}</div><div class="device-details">${[['Tecnologia',r.technology],['Qualità segnale',r.signal+'%'],['Ultima lettura',r.reading],['Consumo',r.consumption.toLocaleString('it-IT')+' '+r.unit],['Distretto',r.district],['Modalità','Telelettura automatica']].map(([l,v])=>`<div class="device-detail"><small>${l}</small><strong>${v}</strong></div>`).join('')}</div><div style="margin-top:22px">${lineChart()}</div><div class="modal-callout">${r.status==='Allarme'?'È presente un evento da verificare. Apri gli allarmi della POC per la presa in carico.':r.status==='Offline'?'Ultima comunicazione non recente. Verifica la connettività del gateway.':'Il dispositivo comunica regolarmente. Nessuna anomalia nelle ultime letture.'}</div>`,btn('Chiudi','close-overlay')+btn('Esporta letture','export-device','primary','download',`data-id="${r.id}"`))}
function alarmModal(sector,index){const s=SECTORS[sector];const names=[s.alert1,s.alert2,'Comunicazione assente'];modal(names[index],`Evento dimostrativo · ${s.idPrefix}-${840201+index}`,`<div class="flex" style="margin-bottom:19px">${badge(index===0?'Priorità alta':'Da verificare',index===0?'red':'amber',true)}${badge('Non assegnato','')}</div><p>${index===0?`Il sistema ha rilevato un’anomalia nel Distretto Nord. Verifica le ultime letture e pianifica un controllo sul dispositivo.`:index===1?'Un valore fuori dall’intervallo atteso richiede una verifica delle letture recenti.':'Il dispositivo non ha inviato letture nell’intervallo previsto. Verifica lo stato del gateway e il livello di segnale.'}</p><div class="device-details"><div class="device-detail"><small>Rilevato</small><strong>29/10/2026 · 10:34</strong></div><div class="device-detail"><small>Distretto</small><strong>${['Nord','Centro','Sud'][index]}</strong></div></div><div class="modal-callout">La presa in carico è una simulazione e resta valida solo durante questa sessione.</div>`,btn('Chiudi','close-overlay')+btn('Prendi in carico','ack-alarm','primary','check',`data-sector="${sector}" data-index="${index}"`))}
function componentModal(id){const c=COMPONENTS.find(x=>x.id===id);if(!c)return;const markup=componentDemo(id);modal(c.name,`${c.category} · ${currentTemplate().name} · ${state.font}`,`<div class="component-preview">${markup}</div><div class="code-toolbar"><span>Markup HTML · token condivisi in styles.css</span>${btn('Copia HTML','copy-component','small','copy',`data-id="${id}"`)}</div><pre class="code-block">${esc(markup)}</pre><p style="font-size:10px;margin-top:12px;margin-bottom:0">${c.desc} I controlli dimostrativi richiedono gli stili e le interazioni inclusi nel progetto.</p>`,btn('Chiudi','close-overlay'),true)}
function help(){modal('Uno studio, tutte le possibilità.','Una guida veloce per trovare la tua direzione.',`<div class="help-steps">${[['Scegli un linguaggio','Esplora i sei template e applica quello più adatto. Selezionane più di uno per confrontarli.'],['Lavora sui dettagli','Personalizza font, colori, densità e stile dei componenti. Salva i tuoi preferiti nella libreria.'],['Mettilo in contesto','Apri VoltGrid, GasLink o AquaSense per provare il design nelle tre dashboard operative.'],['Porta via le tue scelte','Esporta la configurazione JSON, il mockup HTML o i dati delle tabelle in CSV.']].map(([t,p],i)=>`<div class="help-step"><span>${i+1}</span><div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</div><div class="modal-callout">Le impostazioni vengono salvate su questo browser. Tutti i dati di rete e gli eventi sono dimostrativi.</div>`,btn('Inizia a esplorare','close-overlay','primary','arrow'))}
function searchResults(q=''){const entries=[['Panoramica','panoramica','grid','Workspace'],['Template','template','layers','6 direzioni'],['Componenti','componenti','components','36 componenti'],['Tabelle avanzate','tabelle','table','DataTables · AG Grid'],['Mockup','mockup','mockup','Desktop · Tablet · Mobile'],['Confronta template','confronta','compare','Confronto'],...Object.entries(SECTORS).map(([id,s])=>[s.product+' · '+s.name,'poc/'+id,s.icon,'Proof of concept'])];const found=entries.filter(e=>e.join(' ').toLowerCase().includes(q.toLowerCase()));const comps=q?COMPONENTS.filter(c=>(c.name+' '+c.category).toLowerCase().includes(q.toLowerCase())).slice(0,6):[];return `<small>${q?'Risultati':'Vai a'}</small>${found.map(([l,path,ic,group])=>`<a class="search-item" href="#/${path}" data-route>${icon(ic)}${l}<span>${group}</span></a>`).join('')}${comps.length?'<small>Componenti</small>':''}${comps.map(c=>`<button class="search-item" data-action="component-detail" data-id="${c.id}">${icon(c.icon)}${c.name}<span>${c.category}</span></button>`).join('')}${!found.length&&!comps.length?'<p class="muted" style="padding:20px;font-size:11px">Nessun risultato. Prova “Gas”, “tabelle” o “badge”.</p>':''}`}
function openSearch(){setOverlay(`<div class="overlay modal-overlay" data-backdrop><section class="modal search-modal" role="dialog" aria-modal="true" aria-label="Cerca nello studio"><div class="command-input">${icon('search')}<input id="command-search" placeholder="Cerca pagine e componenti…" aria-label="Cerca pagine e componenti"><button class="icon-btn" data-action="close-overlay" aria-label="Chiudi ricerca"><kbd>esc</kbd></button></div><div class="modal-body"><div class="search-results" id="search-results">${searchResults()}</div></div></section></div>`);$('#command-search').focus()}
function download(name,content,type='application/json'){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(rows){const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';return '\uFEFF'+[['Matricola','Indirizzo','Distretto','Stato','Tecnologia','Consumo','Unità','Segnale','Ultima lettura'],...rows.map(r=>[r.id,r.address,r.district,r.status,r.technology,String(r.consumption).replace('.',','),r.unit,r.signal+'%',r.reading])].map(row=>row.map(cell).join(';')).join('\r\n')}
function exportTable(){let rows=[];if(dataTable)rows=dataTable.rows({search:'applied'}).data().toArray();else if(gridApi){const selected=gridApi.getSelectedRows();if(selected.length)rows=selected;else gridApi.forEachNodeAfterFilterAndSort(n=>rows.push(n.data))}else rows=makeRows(tableSector);download(`regenesy-${tableSector}-${tableEngine}.csv`,csv(rows),'text/csv;charset=utf-8');toast(`Esportati ${rows.length} dispositivi in CSV.`)}
async function exportMockup(){const css=await fetch('./styles.css').then(r=>r.text());const fontSource=await fetch('./vendor/fonts.css').then(r=>r.text());const faces=(fontSource.match(/@font-face\s*\{[^}]*\}/g)||[]).filter(f=>f.includes("font-family: '"+state.font+"'"));const embedded=await Promise.all(faces.map(async face=>{const match=face.match(/url\(\.\/([^)]+)\)/);if(!match)return face;const blob=await fetch('./vendor/'+match[1]).then(r=>r.blob());const url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob)});return face.replace(match[0],'url('+url+')')}));const t=currentTemplate();download(`regenesy-${mockSector}-${t.id}-${mockDevice}.html`,`<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${SECTORS[mockSector].product} — Mockup ${t.name}</title><style>${embedded.join('\n')}${css}\nbody{padding:35px;display:grid;place-items:center;min-height:100vh}.mockup-frame{max-width:1000px}body{--font:'${state.font}',system-ui,sans-serif}</style></head><body data-template="${state.template}" data-mode="${state.mode}" data-expression="${state.expression}" style="${state.accent?'--accent:'+state.accent+';':''}"><div style="max-width:1000px;width:100%"><p style="font-size:11px;margin-bottom:18px;color:var(--muted)">REGENESY STUDIO / ${t.name} / ${mockDevice} / Dati dimostrativi</p>${mockupContent()}</div></body></html>`,'text/html');toast('Mockup HTML esportato, pronto da aprire e condividere.')}
const ackedAlarms=new Set();
function updateAlarmUI(){const r=route();if(r.page!=='poc')return;const count=[...ackedAlarms].filter(k=>k.startsWith(r.sector+':')).length;$('#alarm-count').innerHTML=`${SECTORS[r.sector].alerts-count}<em>eventi</em>`;$$('[data-action="alarm-detail"]').forEach(b=>{if(ackedAlarms.has(`${b.dataset.sector}:${b.dataset.index}`)){b.querySelector('span:last-child').innerHTML='<span class="badge green">In carico</span>';b.classList.remove('critical')}})}
document.addEventListener('click',async e=>{
 const routeLink=e.target.closest('[data-route]');if(routeLink){closeOverlay(false);$('#sidebar')?.classList.remove('mobile-open');$('.notification-popover')?.remove()}
 if(e.target.matches('[data-backdrop]')){closeOverlay();return}
 const b=e.target.closest('[data-action]');
 if(!b){const row=e.target.closest('[data-device-id]');if(row){const d=tableRows.find(r=>r.id===row.dataset.deviceId);if(d)deviceModal(d)}const p=e.target.closest('[data-poc-device]');if(p)deviceModal(makeRows(p.dataset.sector,5)[Number(p.dataset.pocDevice)]);if(!e.target.closest('.notification-popover'))$('.notification-popover')?.remove();return}
 const a=b.dataset.action;
 switch(a){
 case 'mobile-nav':{const opened=$('#sidebar').classList.toggle('mobile-open');b.setAttribute('aria-expanded',opened);b.setAttribute('aria-label',opened?'Chiudi navigazione':'Apri navigazione');break}
 case 'close-nav':$('#sidebar').classList.remove('mobile-open');$('[data-action=mobile-nav]')?.setAttribute('aria-expanded','false');break;
 case 'settings':openSettings();break;
 case 'help':help();break;
 case 'search':openSearch();break;
 case 'toggle-mode':state.mode=state.mode==='dark'?'light':'dark';save();render(true);toast(state.mode==='dark'?'Modalità scura attivata.':'Tema originale del template ripristinato.');break;
 case 'close-overlay':closeOverlay();break;
 case 'close-toast':$('#toast-root').innerHTML='';break;
 case 'apply-template':applyTemplate(b.dataset.id);break;
 case 'settings-template':{const scroll=$('.drawer-content').scrollTop;applyTemplate(b.dataset.id,true);$('.drawer-content').scrollTop=scroll;break}
 case 'preview-template':{const t=TEMPLATES.find(x=>x.id===b.dataset.id);modal(t.name,t.desc,`<div style="${previewVars(t)}" class="compare-body">${miniApp(t)}<div class="compare-detail">${badge(t.font,'')}${badge(t.personality,'')}${badge('Raggio '+t.radius+' px','')}</div><p style="font-size:11px;color:var(--preview-muted)">${t.level}. Applica questo template per vederlo su componenti, tabelle e proof of concept.</p></div>`,btn('Chiudi','close-overlay')+btn('Applica template','apply-template','primary','check',`data-id="${t.id}"`));break}
 case 'setting':updateSetting(b.dataset.key,b.dataset.value);break;
 case 'accent':{state.accent=b.dataset.value||null;save();const y=$('.drawer-content').scrollTop;render(true);openSettings();$('.drawer-content').scrollTop=y;break}
 case 'export-config':download('regenesy-studio-configurazione.json',JSON.stringify({schema:'regenesy-studio-v1',...state},null,2));toast('Configurazione esportata.');break;
 case 'reset-config':Object.assign(state,{...DEFAULTS,favorites:[],selected:[]});save();render(true);openSettings();toast('Preferenze originali ripristinate.');break;
 case 'clear-compare':state.selected=[];save();$('#compare-root').innerHTML='';$$('[data-select-template]').forEach(x=>x.checked=false);break;
 case 'template-category':templateCategory=b.dataset.value;render(true);break;
 case 'component-category':componentCategory=b.dataset.value;$$('[data-action="component-category"]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',x===b)});updateComponentGrid();break;
 case 'clear-component-filters':componentCategory='Tutti';componentSearch='';onlyFavorites=false;render(true);break;
 case 'only-favorites':onlyFavorites=!onlyFavorites;b.classList.toggle('primary',onlyFavorites);b.setAttribute('aria-pressed',onlyFavorites);updateComponentGrid();break;
 case 'favorite':{const id=b.dataset.id;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();updateComponentGrid();break}
 case 'component-detail':componentModal(b.dataset.id);break;
 case 'copy-component':try{await navigator.clipboard.writeText(componentDemo(b.dataset.id));toast('Markup HTML copiato.')}catch{const code=$('.code-block');const sel=window.getSelection();const range=document.createRange();range.selectNodeContents(code);sel.removeAllRanges();sel.addRange(range);toast('Markup selezionato. Usa Ctrl+C o ⌘C per copiarlo.')}break;
 case 'table-engine':tableEngine=b.dataset.value;render(true);break;
 case 'reset-table':tableQuery='';tableStatus='';$('#table-search').value='';$('#table-status').value='';if(gridApi){gridApi.resetColumnState();gridApi.deselectAll()}filterTable();toast('Ricerca, filtri e colonne ripristinati.');break;
 case 'export-table':exportTable();break;
 case 'open-sector-table':tableSector=b.dataset.sector;tableStatus='';tableQuery='';location.hash='/tabelle';break;
 case 'poc-alarms':tableSector=b.dataset.sector;tableStatus='Allarme';tableQuery='';location.hash='/tabelle';break;
 case 'chart-period':{period=b.dataset.value;const s=route().sector;$('#poc-chart').innerHTML=bigChart(s);$('#chart-period-label').textContent=(period==='day'?'Andamento nelle ultime 24 ore':period==='week'?'Andamento settimanale':'Andamento mensile')+' · '+SECTORS[s].unit;$$('[data-action="chart-period"]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});break}
 case 'pause-poc':pocPaused=!pocPaused;render(true);updateAlarmUI();break;
 case 'node-detail':{const s=SECTORS[b.dataset.sector],i=Number(b.dataset.index);modal(s.nodes[i],s.network,`<div class="between"><div class="flex"><div class="sector-icon" style="--sector:${s.color}">${icon(s.icon)}</div><h3>${s.nodeValues[i]}</h3></div>${badge('In servizio','green',true)}</div><div class="device-details">${[['Tipologia',i===0?'Nodo di alimentazione':'Nodo di distribuzione'],['Ultimo aggiornamento','29/10/2026 · 10:42'],['Settore',s.name],['Connessione','Attiva']].map(([l,v])=>`<div class="device-detail"><small>${l}</small><strong>${v}</strong></div>`).join('')}</div><div style="margin-top:24px">${lineChart(s.color,i)}</div><div class="modal-callout">Dati simulati per esplorare lo schema di rete e le interazioni del prodotto.</div>`,btn('Chiudi','close-overlay'));break}
 case 'alarm-detail':{const k=`${b.dataset.sector}:${b.dataset.index}`;if(ackedAlarms.has(k)){modal('Evento preso in carico','Simulazione di gestione allarmi',`<div class="modal-callout">${icon('check')} Questo evento è già assegnato al tuo workspace per la sessione corrente.</div>`,btn('Chiudi','close-overlay','primary'))}else alarmModal(b.dataset.sector,Number(b.dataset.index));break}
 case 'ack-alarm':ackedAlarms.add(`${b.dataset.sector}:${b.dataset.index}`);closeOverlay();updateAlarmUI();toast('Allarme preso in carico nel workspace dimostrativo.');break;
 case 'export-poc':download(`regenesy-${b.dataset.sector}-report.csv`,csv(makeRows(b.dataset.sector)),'text/csv;charset=utf-8');toast('Report CSV dei dispositivi esportato.');break;
 case 'export-device':{const r=tableRows.find(x=>x.id===b.dataset.id)||Object.keys(SECTORS).flatMap(s=>makeRows(s,64)).find(x=>x.id===b.dataset.id);if(r){download(`letture-${r.id}.csv`,csv([r]),'text/csv;charset=utf-8');toast('Lettura del dispositivo esportata.')}break}
 case 'mock-device':mockDevice=b.dataset.value;render(true);break;
 case 'export-mockup':try{await exportMockup()}catch{toast('Impossibile esportare il mockup. Riprova.')}break;
 case 'notifications':{const old=$('.notification-popover');if(old){old.remove();break}document.body.insertAdjacentHTML('beforeend',`<section class="notification-popover" role="region" aria-label="Novità dello studio"><div class="between"><h3>Dentro lo studio</h3><button class="icon-btn" data-action="close-notifications" aria-label="Chiudi novità">${icon('close')}</button></div>${[['layers','Sei direzioni, tutte da esplorare.','I template sono pronti per il confronto.'],['table','Due motori per i tuoi dati.','Prova DataTables e AG Grid nel registro.'],['shield','Le tue scelte restano con te.','Le preferenze vengono salvate nel browser.']].map(([ic,t,d])=>`<div class="notification-entry">${icon(ic)}<div><strong style="font-weight:550">${t}</strong><small>${d}</small></div></div>`).join('')}</section>`);break}
 case 'close-notifications':$('.notification-popover')?.remove();break;
 case 'demo-toast':toast('Azione completata nell’anteprima dimostrativa.');break;
 case 'demo-download':download('regenesy-letture-esempio.csv',csv(makeRows('idrico',8)),'text/csv;charset=utf-8');toast('Letture dimostrative esportate.');break;
 case 'demo-chip':b.classList.toggle('active');b.setAttribute('aria-pressed',b.classList.contains('active'));break;
 case 'demo-tab':{const group=b.closest('.component-preview');$$('.demo-tabs button',group).forEach(x=>x.classList.toggle('active',x===b));$('[data-tab-text]',group).textContent={'Panoramica':'Stato generale del dispositivo','Letture':'Ultima lettura: 128,6 m³ · Oggi, 10:42','Eventi':'2 eventi di rete nelle ultime 24 ore'}[b.textContent];break}
 case 'demo-page':{const group=b.closest('.component-preview'),current=Number($('.demo-pagination button.active',group).dataset.page);const next=b.dataset.page==='prev'?Math.max(1,current-1):b.dataset.page==='next'?Math.min(4,current+1):Number(b.dataset.page);$$('.demo-pagination button',group).forEach(x=>x.classList.toggle('active',Number(x.dataset.page)===next));$('[data-page-text]',group).textContent=`Pagina ${next} di 4`;break}
 case 'demo-step':{const group=b.closest('.component-preview'),steps=$$('.step-circle',group);let n=steps.findIndex(x=>x.classList.contains('active'));n=n<0?0:n+1;steps.forEach((x,i)=>{x.className='step-circle '+(i<n?'done':i===n?'active':'');x.innerHTML=i<n?icon('check'):i+1});b.textContent=n>=3?'Ricomincia':'Passo successivo';break}
 case 'demo-progress':{const g=b.closest('.component-preview'),v=Number($('[data-progress-value]',g).textContent.replace('%',''));const n=v>=100?0:Math.min(v+16,100);$('[data-progress-value]',g).textContent=n+'%';$('.progress-track i',g).style.width=n+'%';b.textContent=n>=100?'Ricomincia':'Avanza';break}
 case 'bar-value':toast(b.dataset.value);break;
 case 'demo-alert':alarmModal('idrico',0);break;
 case 'demo-modal':modal('Aggiungi un dispositivo','Un esempio di dialog con validazione.',`<form id="demo-device-form"><label class="field"><span>Nome dispositivo</span><input class="input" id="demo-name" placeholder="Es. Gateway Nord 02" required minlength="3" maxlength="60"><small class="field-hint">Almeno 3 caratteri.</small></label><label class="field"><span>Distretto</span><select class="input"><option>Distretto Nord</option><option>Distretto Centro</option><option>Distretto Sud</option></select></label></form><div class="modal-callout">Il dispositivo verrà aggiunto solo all’anteprima dimostrativa.</div>`,btn('Annulla','close-overlay')+btn('Aggiungi dispositivo','save-demo','primary','plus'));break;
 case 'save-demo':if($('#demo-device-form').reportValidity()){const n=$('#demo-name').value;closeOverlay();toast(`${n} aggiunto all’anteprima.`)}break;
 }
});
document.addEventListener('input',e=>{if(e.target.id==='component-search'){componentSearch=e.target.value;updateComponentGrid()}if(e.target.id==='table-search'){tableQuery=e.target.value;filterTable()}if(e.target.id==='command-search')$('#search-results').innerHTML=searchResults(e.target.value);if(e.target.matches('.demo-range'))e.target.closest('.demo-field').querySelector('[data-range-value]').textContent=e.target.value+'%'});
document.addEventListener('change',async e=>{const t=e.target;
 if(t.matches('[data-select-template]')){const id=t.dataset.selectTemplate;state.selected=t.checked?[...new Set([...state.selected,id])]:state.selected.filter(x=>x!==id);save();$('#compare-root').innerHTML=compareBar()}
 if(t.id==='font-select')updateSetting('font',t.value);
 if(t.id==='motion-switch')updateSetting('motion',t.checked);
 if(t.id==='table-sector'){tableSector=t.value;render(true)}
 if(t.id==='table-status'){tableStatus=t.value;filterTable()}
 if(t.id==='mock-sector'){mockSector=t.value;render(true)}
 if(t.matches('.demo-file')){const f=t.files[0];if(f){t.parentElement.querySelector('[data-upload-name]').textContent=f.name;toast(`File selezionato: ${f.name}`)}}
 if(t.id==='import-config'&&t.files[0]){try{const conf=JSON.parse(await t.files[0].text());if(conf.schema!=='regenesy-studio-v1')throw Error();if(!TEMPLATES.some(x=>x.id===conf.template)||!['Inter','Manrope','DM Sans','IBM Plex Sans','Plus Jakarta Sans'].includes(conf.font))throw Error();const next={...DEFAULTS};for(const k of Object.keys(DEFAULTS))if(k in conf)next[k]=conf[k];if(!['light','dark'].includes(next.mode)||!['compact','comfortable'].includes(next.density)||!['rigorous','balanced','expressive'].includes(next.expression)||typeof next.motion!=='boolean'||(next.accent&&!/^#[a-f0-9]{6}$/i.test(next.accent))||!Array.isArray(next.favorites)||!Array.isArray(next.selected))throw Error();next.favorites=next.favorites.filter(id=>COMPONENTS.some(c=>c.id===id));next.selected=next.selected.filter(id=>TEMPLATES.some(t=>t.id===id));Object.assign(state,next);save();render(true);openSettings();toast('Configurazione importata e applicata.')}catch{toast('File non valido. Importa una configurazione esportata da Regenesy Studio.')}}
});
document.addEventListener('submit',e=>{if(e.target.id==='demo-device-form'){e.preventDefault();$('[data-action="save-demo"]').click()}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}if(e.key==='Escape'){closeOverlay();$('.notification-popover')?.remove();$('#sidebar')?.classList.remove('mobile-open')}if(e.key==='Enter'&&e.target.matches('[data-device-id],[data-poc-device],.network-node')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}if(e.key==='Tab'&&$('#overlay-root').children.length){const all=$$('button:not([disabled]),a[href],input:not([type=hidden]),select,textarea,summary,[tabindex="0"]',$('#overlay-root')).filter(el=>el.offsetParent!==null);const first=all[0],last=all[all.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
window.addEventListener('hashchange',()=>{closeOverlay(false);render();updateAlarmUI()});
render();updateAlarmUI();
